		public static extern unsafe int WSCInstallProvider64_32(global::System.Guid* lpProviderId, winmdroot.Foundation.PCWSTR lpszProviderDllPath, winmdroot.Networking.WinSock.WSAPROTOCOL_INFOW* lpProtocolInfoList, uint dwNumberOfEntries, int* lpErrno);

