		/// </remarks>
		[DllImport("WS2_32.dll", ExactSpelling = true, EntryPoint = "InetNtopW"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)]
		[SupportedOSPlatform("windows8.1")]
		public static extern unsafe winmdroot.Foundation.PCWSTR InetNtop(int Family, void* pAddr, winmdroot.Foundation.PWSTR pStringBuf, nuint StringBufSize);

